(() => {
  const keep = new Set([...Object.keys(BUILDINGS_BY_KEYS), ...TERRAINS.map(t => t.grid_key), ...["water", "deep_water", "forest", "hill", "mountain", "river", "has_street", "has_bridge", "otocenie", "rails", "pavement", "pavement_w", "mesto", "vidiek", "mega_city", "eco_city", "farmfield", "farmfield2", "farmfield_used", "farmfield_pumpkin", "farmfield_turkey", "farmfield_turkey2", "swamp", "swamp_rocks", "desert", "sand", "scorched", "disrupted_earth", "rubble1", "rubble2", "rubble3", "rubble4", "fish", "fish_small", "fish_big", "fish_huge", "water_rocks", "ship_wreck", "ship_wreck_small", "artifact", "is_connected", "isNextToTown", "lava_rift", "broken_city_small", "broken_city_medium", "broken_rail", "uranium_cloud", "special_tile", "empty_water", "building_type"]]);
  const rows = [];
  for (const x in myGridData) for (const y in myGridData[x]) {
    const g = myGridData[x][y]; if (!g || g.x === undefined) continue;
    const f = {};
    for (const k in g) { if (!keep.has(k)) continue; const v = g[k]; if (v && typeof v !== 'object' && typeof v !== 'function') f[k] = v === true ? 1 : v; }
    rows.push([g.x, g.y, f]);
  }
  return rows;
})()
